3: 
4: import 'widgets/widgets.dart';
5: 
6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage>
14:     with SingleTickerProviderStateMixin, WidgetsBindingObserver {
15:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
16: 
17:   late final AnimationController _fadeController;
18: 
19:   // Pagination state
20:   int _currentPage = 0;
21:   List<CurrencyModel> _allCurrencies = [];
22:   List<CurrencyModel> _displayedCurrencies = [];
23:   bool _hasMore = false;
24:   bool _isLoading = false;
25:   bool _hasLostFocus = false;
26: 
27:   String _searchQuery = '';
28: 
29:   @override
30:   void initState() {
31:     super.initState();
32:     WidgetsBinding.instance.addObserver(this);
33:     _initAnimation();
34:     _loadInitialPage();
35:   }
36: 
37:   @override
38:   void didChangeDependencies() {
39:     super.didChangeDependencies();
40:     // При потере фокуса экрана (например, когда экран становится inactive)
41:     // запоминаем это для последующей перезагрузки данных при возврате.
42:     final route = ModalRoute.of(context);
43:     if (route != null && !route.isCurrent) {
44:       _hasLostFocus = true;
45:     }
46:   }
47: 
48:   @override
49:   void didChangeAppLifecycleState(AppLifecycleState state) {
50:     super.didChangeAppLifecycleState(state);
51:     if (state == AppLifecycleState.resumed && _hasLostFocus) {
52:       // Возвращаемся на экран — перезагружаем данные с первой страницы.
53:       setState(() => _hasLostFocus = false);
54:       _loadInitialPage();
55:     } else if (state == AppLifecycleState.inactive ||
56:         state == AppLifecycleState.paused) {
57:       // Потеряли фокус приложения/экрана — запоминаем это.
58:       _hasLostFocus = true;
59:     }
60:   }
61: 
62:   @override
63:   void dispose() {
64:     WidgetsBinding.instance.removeObserver(this);
65:     _filteredCurrenciesNotifier.dispose();
66:     _fadeController.dispose();
67:     super.dispose();
68:   }
69: 
70:   void _initAnimation() {
71:     _fadeController = AnimationController(
72:       duration: const Duration(milliseconds: 400),
73:       vsync: this,
74:     );
75:   }
76: 
77:   Future<void> _loadInitialPage() async {
78:     setState(() {
79:       _displayedCurrencies = [];
80:       _hasMore = false;
81:       _currentPage = 0;
82:       _allCurrencies = [];
83:       _isLoading = true;
84:     });
85: 
86:     final currencyRepository = context.read<CurrencyRepository>();
87:     final page = await currencyRepository.fetchRates(
88:       const CurrencyPageRequest(base: 'EUR'),
89:     );
90: 
91:     setState(() {
92:       _currentPage = 0;
93:       _allCurrencies = List.from(page.items);
94:       _displayedCurrencies = List.from(page.items);
95:       _hasMore = page.hasMore;
96:       _isLoading = false;
97:     });
98: 
