{"content":"import 'dart:async';

import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  static const String _defaultBase = 'EUR';

  late final AnimationController _fadeController;
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  // Пагинация: все загруженные элементы и отображаемые.
  List<CurrencyModel> _allCurrencies = [];
  List<CurrencyModel> _displayedCurrencies = [];
  int _currentPage = 0;
  bool _hasMore = false;
  bool _isLoading = false;

  // Поиск.
  String _searchQuery = '';

  // Счётчик "потерь фокуса" для детекции ухода/возврата с экрана.
  int _focusLossCount = 0;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _filteredCurrenciesNotifier = ValueNotifier([]);
    _loadInitialPage();
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();

    // При потере фокуса экрана (вкладка/навигация уходит) — запоминаем.
    final route = ModalRoute.of(context);
    if (route != null && !route.isCurrent) {
      _markFocusLoss();
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    super.didChangeAppLifecycleState(state);
    if (state == AppLifecycleState.resumed && _focusLossCount > 0) {
      // Возвращаемся на экран — перезагружаем данные с первой страницы.
      setState(() => _focusLossCount = 0);
      _loadInitialPage();
    } else if (state == AppLifecycleState.inactive ||
        state == AppLifecycleState.paused) {
      _markFocusLoss();
    }
  }

  void _markFocusLoss() {
    setState(() => _focusLossCount++);
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitialPage() async {
    if (mounted) {
      setState(() {
        _displayedCurrencies = [];
        _allCurrencies = [];
        _hasMore = false;
        _currentPage = 0;
        _isLoading = true;
      });
    }

    final currencyRepository = context.read<CurrencyRepository>();
    final page = await currencyRepository.fetchRates(
      const CurrencyPageRequest(base: _defaultBase),
    );

    if (mounted) {
      setState(() {
        _currentPage = 0;
        _allCurrencies = List.from(page.items);
        _displayedCurrencies = List.from(page.items);
        _hasMore = page.hasMore;
        _isLoading = false;
      });

      _filterCurrencies(_searchQuery);
      currencyRepository.saveCurrencyList(_allCurrencies);
      if (_fadeController.status != AnimationStatus.forward) {
        _fadeController.forward(from: 0.0);
      }
    }
  }

  Future<void> _loadNextPage() async {
    if (_isLoading || !_hasMore || _searchQuery.isNotEmpty) return;

    setState(() => _isLoading = true);

    final nextPage = _currentPage + 1;
    final currencyRepository = context.read<CurrencyRepository>();
    final page = await currencyRepository.fetchRates(
      CurrencyPageRequest(base: _defaultBase, page: nextPage),
    );

    if (mounted) {
      setState(() {
        _currentPage = page.page;
        _allCurrencies.addAll(page.items);
        _displayedCurrencies.addAll(page.items);
        _hasMore = page.hasMore;
        _isLoading = false;
      });
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    _searchQuery = query;

    List<CurrencyModel> source;
    if (query.isEmpty) {
      // При пустом поиске — показываем пагинированные данные.
      source = _displayedCurrencies;
    } else {
      final Iterable<CurrencyModel> result = _allCurrencies.where(
        (CurrencyModel currency) {
          return currency.name.toLowerCase().contains(lowerQuery) ||
              currency.symbol.toLowerCase().contains(lowerQuery);
        },
      );
      source = result.toList(growable: false);
    }

    if (mounted && _filteredCurrenciesNotifier.value != source) {
      _filteredCurrenciesNotifier.value = source;
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FadeTransition(
        opacity: _fadeController.view,
        child: Column(
          children: [
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
              child: SearchView(onChanged: _filterCurrencies),
            ),
            Expanded(
              child: ValueListenableBuilder<List<CurrencyModel>>(
                valueListenable: _filteredCurrenciesNotifier,
                builder: (BuildContext context, List<CurrencyModel> data, _) {
                  return ListView.builder(
                    itemCount: data.length + (_isLoading && _searchQuery.isEmpty ? 1 : 0),
                    itemBuilder: (BuildContext context, int index) {
                      // Индикатор загрузки при пагинации.
                      if (index >= data.length) {
                        return const Center(child: CircularProgressIndicator());
                      }

                      final CurrencyModel currency = data[index];

                      return Padding(
                        key: ValueKey(currency.id),
                        padding: index == 0
                            ? const EdgeInsets.only(top: 20)
                            : const EdgeInsets.only(top: 10),
                        child: CurrencyCard(model: currency),
                      );
                    },
                    padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                  );
                },
              ),
            ),
            // Кнопка «Показать ещё»: видна только при пустом поиске и наличии следующих страниц.
            if (_searchQuery.isEmpty && _hasMore)
              Padding(
                padding: const EdgeInsets.only(bottom: 20),
                child: ElevatedButton(
                  onPressed: _isLoading ? null : _loadNextPage,
                  child: Text(context.loc.loadMore),
                ),
              ),
          ],
        ),
      ),
    );
  }
}
